// A new seller's first command is `node new-key.ts`, so it is the one with a test. Run: npm test
// (in /spike), or `node --test spike/new-key.test.ts` from the repo root.
//
// Every key this file touches is generated by the run itself, into a fresh temp dir, through
// new-key.ts's NEW_KEY_DIR override. It never reads a real key in /spike.
import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { mkdirSync, mkdtempSync, readdirSync, readFileSync, statSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'
import { getPublicKey, nip19 } from 'nostr-tools'
import { hexToBytes } from '@noble/hashes/utils.js'

const HERE = dirname(fileURLToPath(import.meta.url))
const SCRIPT = join(HERE, 'new-key.ts')

const run = (dir: string, ...args: string[]) =>
  spawnSync(process.execPath, [SCRIPT, ...args], {
    cwd: HERE,
    env: { ...process.env, NEW_KEY_DIR: dir },
    encoding: 'utf8',
  })
const freshDir = () => mkdtempSync(join(tmpdir(), 'new-key-test-'))

test('creates a 64-hex key, mode 0600, under the default name', () => {
  const dir = freshDir()
  const r = run(dir)
  assert.equal(r.status, 0, r.stderr)
  const file = join(dir, '.my-key')
  assert.match(readFileSync(file, 'utf8'), /^[0-9a-f]{64}$/)
  assert.equal(statSync(file).mode & 0o777, 0o600)
})

test('prints the npub of the key it wrote, and never the secret', () => {
  const dir = freshDir()
  const r = run(dir, '.shop-key')
  assert.equal(r.status, 0, r.stderr)
  const hex = readFileSync(join(dir, '.shop-key'), 'utf8')
  const first = r.stdout.split('\n')[0]
  assert.match(first, /^npub1[02-9ac-hj-np-z]+$/)
  assert.equal(first, nip19.npubEncode(getPublicKey(hexToBytes(hex))))
  assert.ok(!r.stdout.includes(hex), 'stdout holds the hex secret')
  assert.ok(!r.stderr.includes(hex), 'stderr holds the hex secret')
  assert.ok(!r.stdout.includes(nip19.nsecEncode(hexToBytes(hex))), 'stdout holds the nsec')
  assert.match(r.stdout, /authorize-manage\.ts --key \.shop-key/)
})

test('refuses to overwrite an existing key and leaves its bytes alone', () => {
  const dir = freshDir()
  assert.equal(run(dir, '.twice-key').status, 0)
  const before = readFileSync(join(dir, '.twice-key'))
  const r = run(dir, '.twice-key')
  assert.notEqual(r.status, 0)
  assert.match(r.stderr, /already exists/)
  assert.deepEqual(readFileSync(join(dir, '.twice-key')), before)
})

test('rejects names the .gitignore glob would not cover, and writes nothing', () => {
  for (const name of ['foo', '../x-key', '.dev-key.nsec', '.x', '.a/b-key']) {
    // Nested, so `..` resolves to a dir this run also owns and checks.
    const parent = freshDir()
    const dir = join(parent, 'spike')
    mkdirSync(dir)
    const r = run(dir, name)
    assert.notEqual(r.status, 0, `accepted ${name}`)
    assert.match(r.stderr, /must match/, name)
    assert.deepEqual(readdirSync(dir), [], `wrote a file for ${name}`)
    assert.deepEqual(readdirSync(parent), ['spike'], `wrote outside the dir for ${name}`)
  }
})

test('README "one step" section introduces new-key.ts before authorize-manage.ts and explains app.nprofile', () => {
  const readme = readFileSync(join(HERE, '..', 'README.md'), 'utf8')
  const start = readme.indexOf('### The one step ShockWallet does not do for you yet')
  assert.ok(start !== -1, 'section heading missing')
  const end = readme.indexOf('\n### ', start + 1)
  const section = readme.slice(start, end === -1 ? undefined : end)

  const block = section.search(/```bash\n(?:[^`]*\n)?node authorize-manage\.ts/)
  assert.ok(block !== -1, 'authorize-manage.ts block missing')
  const helper = section.indexOf('node new-key.ts')
  assert.ok(helper !== -1 && helper < block, 'node new-key.ts is not before the authorize-manage.ts block')

  const para = section.split('\n\n').find(p => p.includes('app.nprofile'))
  assert.ok(para, 'app.nprofile not mentioned in the section')
  assert.match(para, /operator|their machine/)
  assert.match(section, /--key \.my-key/)
})

test("authorize-manage.ts's missing-key error points at new-key.ts, not seed-listings.ts", () => {
  const src = readFileSync(join(HERE, 'authorize-manage.ts'), 'utf8')
  const line = src.split('\n').find(l => l.includes('if (!existsSync(KEY_FILE))'))
  assert.ok(line, 'missing-key check not found')
  assert.match(line, /new-key\.ts/)
  assert.doesNotMatch(line, /seed-listings/)
})
